// Vercel serverless entry (hand-written; api/_app.js is generated by `npm run build:api`).
// The app is loaded lazily so that a startup failure is reported as readable JSON instead of an opaque 500.
let loading;
function load(){return loading??=import('./_app.js').then(m=>m.default)}
export default async function handler(req,res){
  try{
    const app=await load();
    return app(req,res);
  }catch(e){
    loading=undefined;
    console.error('SocialOrbit API failed to start:',e);
    const detail=String(e&&e.message||e).replace(/\/var\/task\//g,'').slice(0,300);
    res.statusCode=500;res.setHeader('content-type','application/json');
    res.end(JSON.stringify({error:'The API failed to start',code:'STARTUP_FAILED',detail}));
  }
}
